/**
 * Rows for the Golden Bot versus Death Wave chart: for every Golden Bot cooldown and Death Wave
 * offset, how often the two line up, computed rather than transcribed.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    computeGoldBotDeathWaveRows
 * depends    src/charts/datasets/types
 * used by    src/calculators/specs.generated, src/charts/datasets/index, src/charts/index, src/charts/tables/lookup
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { GoldBotDeathWaveRow } from './types'

const DW_OFFSETS = [2, 3, 4, 5, 6, 7, 8] as const

export function computeGoldBotDeathWaveRows(): GoldBotDeathWaveRow[] {
  const rows: GoldBotDeathWaveRow[] = []

  for (let gbCooldownSec = 38; gbCooldownSec <= 65; gbCooldownSec += 1) {
    for (const deathWaveOffsetSec of DW_OFFSETS) {
      const syncPercent = computeSyncPercent(gbCooldownSec, deathWaveOffsetSec)
      rows.push({ gbCooldownSec, deathWaveOffsetSec, syncPercent })
    }
  }

  return rows
}

function computeSyncPercent(gbCooldownSec: number, deathWaveOffsetSec: number): number {
  const cycleWindowSec = 600
  const gbTriggers = buildTriggerTimes(gbCooldownSec, cycleWindowSec)
  const dwTriggers = buildTriggerTimes(120 + deathWaveOffsetSec, cycleWindowSec)

  let synced = 0
  for (const gbTrigger of gbTriggers) {
    if (dwTriggers.some(dwTrigger => Math.abs(dwTrigger - gbTrigger) <= 1)) {
      synced += 1
    }
  }

  if (gbTriggers.length === 0) {
    return 0
  }

  return Math.round((synced / gbTriggers.length) * 100)
}

function buildTriggerTimes(intervalSec: number, horizonSec: number): number[] {
  const values: number[] = []
  for (let t = intervalSec; t <= horizonSec; t += intervalSec) {
    values.push(t)
  }
  return values
}
